<template><div class="toolbar"><a-button type="primary" @click="openCreate"><PlusOutlined/>添加账号</a-button><span class="muted">支持 115、百度网盘、OpenList 与 123 云盘</span></div><a-spin :spinning="loading"><a-list :data-source="accounts" :grid="{gutter:16,xs:1,lg:2}"><template #renderItem="{item}"><a-list-item><a-card class="panel-card"><a-card-meta :title="item.name||item.username||`账号 #${item.id}`" :description="`${item.source_type} · ${item.username||item.user_id||'未授权'}`"><template #avatar><a-avatar :style="{background:'#eef0ff',color:'#5b6cf9'}">{{item.source_type[0].toUpperCase()}}</a-avatar></template></a-card-meta><div class="account-actions"><a-tag :color="item.token_failed_reason?'error':item.username||item.token?'success':'default'">{{item.token_failed_reason?'授权异常':item.username||item.token?'已授权':'未授权'}}</a-tag><div class="grow"/><a-button v-if="item.source_type==='115'" size="small" @click="cookieAccount=item;cookieVisible=true">{{item.cookie_bound?'更新':'绑定'}} Cookie</a-button><a-button v-if="['115','baidupan'].includes(item.source_type)" size="small" @click="authorize(item)">授权</a-button><a-popconfirm title="确定删除账号？" @confirm="remove(item.id)"><a-button danger size="small">删除</a-button></a-popconfirm></div></a-card></a-list-item></template></a-list></a-spin><a-modal v-model:open="createVisible" title="添加网盘账号" @ok="saveAccount"><a-form layout="vertical"><a-form-item label="账号类型"><a-select v-model:value="form.source_type" :options="sourceOptions"/></a-form-item><template v-if="form.source_type==='openlist'"><a-form-item label="服务地址"><a-input v-model:value="form.base_url"/></a-form-item><a-form-item label="用户名"><a-input v-model:value="form.username"/></a-form-item><a-form-item label="密码"><a-input-password v-model:value="form.password"/></a-form-item><a-form-item label="Token"><a-input-password v-model:value="form.token"/></a-form-item></template><template v-else><a-form-item label="账号名称"><a-input v-model:value="form.name"/></a-form-item><a-form-item v-if="form.source_type==='115'" label="应用"><a-select v-model:value="form.app_id_name" :options="appOptions"/></a-form-item></template></a-form></a-modal><a-modal v-model:open="cookieVisible" title="绑定 115 Cookie" @ok="saveCookie"><a-textarea v-model:value="cookie" :rows="7" placeholder="粘贴完整 Cookie"/></a-modal></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{message}from'ant-design-vue';import{PlusOutlined}from'@ant-design/icons-vue';import{del,get,post}from'../../services/http';import type{Account}from'../../types';const accounts=ref<Account[]>([]),loading=ref(true),createVisible=ref(false),cookieVisible=ref(false),cookieAccount=ref<Account>(),cookie=ref(''),form=reactive({source_type:'115',name:'',app_id_name:'QMediaSync',base_url:'',username:'',password:'',token:''});const sourceOptions=[['115','115 网盘'],['baidupan','百度网盘'],['openlist','OpenList'],['123','123 云盘']].map(([value,label])=>({value,label})),appOptions=['QMediaSync','Q115-STRM','MQ的媒体库'].map(value=>({value,label:value}));async function load(){loading.value=true;try{accounts.value=await get('/account/list')}finally{loading.value=false}}function openCreate(){createVisible.value=true}async function saveAccount(){if(form.source_type==='openlist')await post('/account/openlist',form);else await post('/account/add',form);createVisible.value=false;message.success('账号已保存');load()}async function saveCookie(){await post('/account/115-cookie',{id:cookieAccount.value?.id,cookie:cookie.value});cookieVisible.value=false;cookie.value='';message.success('Cookie 已绑定');load()}async function remove(id:number){await post('/account/delete',{id});load()}async function authorize(a:Account){const route=a.source_type==='115'?'/115/oauth-url':'/baidupan/oauth-url',url=await get<string>(`${route}?account_id=${a.id}&redirect_url=${encodeURIComponent(location.origin+location.pathname)}`);window.location.href=url}onMounted(load)</script>
<style scoped>.account-actions{display:flex;align-items:center;gap:8px;margin-top:20px}</style>
